    if(b.operation==='subtraction'){const noteVals=state.difficulty==='hard'?b.borrowNotes:(activeTask?.borrowNotes||b.borrowNotes);stage.appendChild(row('regroup',noteVals,'',null,'','note-cell'));stage.appendChild(row('top',b.top,'',null,'','',noteVals))}
